diameter.normalizedSource:
"use geosolve sketch";
import { sketch, mm } from "@geosolve/sketch-code";

export default sketch(($) => {
  const bore = $.geometry.centerRadiusCircle("bore", {
    center: [0, 0],
    radius: mm(2),
  });
  const dimension1 = $.dimension.diameter("dimension1", {
    curve: bore.curve,
    isKeyConstraint: true,
    label: "Diameter",
    mode: "reference",
    value: mm(4),
  });
  $.group("Canvas additions", [dimension1]);
  return {
    bore: bore,
  };
});

